previewCss:
.darma-loader-darma-b11-butterfly { --accent: var(--loader-color, #8b5cf6); --accent-2: var(--loader-secondary-color, #f0abfc); width: var(--loader-size, 84px); height: var(--loader-size, 84px); position: relative; display: grid; place-items: center; }
.darma-loader-darma-b11-butterfly span { position: absolute; width: 40%; height: 58%; background: radial-gradient(circle at 50% 38%, color-mix(in srgb, #fff 25%, var(--accent-2)), var(--accent)); border-radius: 50% 50% 50% 50% / 62% 62% 38% 38%; }
.darma-loader-darma-b11-butterfly span:nth-child(1) { left: 8%; transform-origin: right center; animation: darma-loader-darma-b11-butterfly-flap-l calc(var(--loader-speed, 1s) * .6) ease-in-out infinite; }
.darma-loader-darma-b11-butterfly span:nth-child(2) { right: 8%; transform-origin: left center; animation: darma-loader-darma-b11-butterfly-flap-r calc(var(--loader-speed, 1s) * .6) ease-in-out infinite; }
.darma-loader-darma-b11-butterfly::after { content: ''; position: absolute; left: 50%; top: 22%; width: calc(var(--loader-size, 84px) * .045); height: 56%; margin-left: calc(var(--loader-size, 84px) * -.0225); background: #1e293b; border-radius: 4px; z-index: 2; }
@keyframes darma-loader-darma-b11-butterfly-flap-l { 0%, 100% { transform: perspective(220px) rotateY(0deg); } 50% { transform: perspective(220px) rotateY(72deg); } }
@keyframes darma-loader-darma-b11-butterfly-flap-r { 0%, 100% { transform: perspective(220px) rotateY(0deg); } 50% { transform: perspective(220px) rotateY(-72deg); } }

